INSERT INTO _migration_615_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igphy_space_s3_001', 'topic_igcse_physics_space', 'subj_igcse_physics', 'igcse', NULL, NULL, 'Which planet in the Solar System is closest to the Sun?', 'multiple_choice', NULL, '["A. Mercury","B. Venus","C. Earth","D. Mars"]', 'A', 'The order of the planets from the Sun is Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune, so Mercury is closest and experiences the strongest gravitational pull and the shortest orbital period. Therefore the correct answer is A: Mercury.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Recall', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igphy_space_s3_002', 'topic_igcse_physics_space', 'subj_igcse_physics', 'igcse', NULL, NULL, 'What is the name of the galaxy that contains our Solar System?', 'multiple_choice', NULL, '["A. Andromeda","B. The Milky Way","C. The North Star","D. The Solar Nebula"]', 'B', 'The Solar System lies in the Milky Way, a spiral galaxy containing billions of stars. Andromeda is the nearest large galaxy to our own, the North Star (Polaris) is a single star within the Milky Way, and the solar nebula was the cloud from which the Solar System formed, not a galaxy. Therefore the correct answer is B: The Milky Way.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Recall', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igphy_space_s3_003', 'topic_igcse_physics_space', 'subj_igcse_physics', 'igcse', NULL, NULL, 'Approximately how long does the Earth take to make one complete orbit of the Sun?', 'multiple_choice', NULL, '["A. One day (24 hours)","B. One month (about 28 days)","C. One year (about 365 days)","D. One decade (10 years)"]', 'C', 'The Earth completes one orbit of the Sun in about 365 days — one year. One day is the time for the Earth to rotate once on its own axis, which causes day and night, and about 28 days is the orbital period of the Moon around the Earth. Therefore the correct answer is C: One year (about 365 days).', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Recall', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igphy_space_s3_004', 'topic_igcse_physics_space', 'subj_igcse_physics', 'igcse', NULL, NULL, 'Which force keeps the planets in orbit around the Sun?', 'multiple_choice', NULL, '["A. The magnetic field of the Sun","B. Friction between the planet and space","C. Electrostatic attraction between charged particles","D. The gravitational attraction between the Sun and each planet"]', 'D', 'Gravity provides the centripetal force that continually pulls each planet towards the Sun, bending its path into an orbit. Space is essentially a vacuum, so there is no friction, and magnetic and electrostatic forces are far too weak to hold planets in orbit. Therefore the correct answer is D: The gravitational attraction between the Sun and each planet.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igphy_space_s3_005', 'topic_igcse_physics_space', 'subj_igcse_physics', 'igcse', NULL, NULL, 'Why does the Sun appear to move across the sky from east to west during the day?', 'multiple_choice', NULL, '["A. The Earth rotates on its axis once every 24 hours","B. The Sun orbits the Earth once every day","C. The Earth orbits the Sun once every day","D. The Moon blocks the Sun as it moves across the sky"]', 'A', 'The apparent daily motion of the Sun is caused by the Earth spinning eastwards on its axis once every 24 hours, so the Sun appears to rise in the east and set in the west. The Earth’s orbit around the Sun takes a whole year and produces the seasons, not the daily motion. Therefore the correct answer is A: The Earth rotates on its axis once every 24 hours.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igphy_space_s3_006', 'topic_igcse_physics_space', 'subj_igcse_physics', 'igcse', NULL, NULL, 'What observation provides evidence that the Universe is expanding?', 'multiple_choice', NULL, '["A. Light from all galaxies is blueshifted","B. Light from distant galaxies is redshifted, and the further away a galaxy is, the greater its redshift","C. The number of stars in the Milky Way is increasing","D. The planets are moving further from the Sun each year"]', 'B', 'The absorption lines in the spectra of distant galaxies are shifted to longer wavelengths (redshift), showing that the galaxies are receding; the redshift increases with distance, exactly as expected if space itself is expanding. Blueshift would indicate approach, and changes inside our own galaxy or Solar System cannot show the expansion of the Universe. Therefore the correct answer is B: Light from distant galaxies is redshifted, and the further away a galaxy is, the greater its redshift.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igphy_space_s3_007', 'topic_igcse_physics_space', 'subj_igcse_physics', 'igcse', NULL, NULL, 'A star such as the Sun remains stable for billions of years. Which statement best describes this equilibrium?', 'multiple_choice', NULL, '["A. The nuclear reactions switch off the force of gravity","B. The outward pressure from fusion is much greater than gravity, so the star slowly expands","C. The inward force of gravity is balanced by the outward pressure of the hot gas and radiation","D. The star’s mass is too small for gravity to have any effect"]', 'C', 'In a stable star there is a balance (hydrostatic equilibrium): gravity pulls the gas inwards while the pressure of the hot gas and the radiation from nuclear fusion pushes outwards. If gravity were unopposed the star would collapse, and if the pressure were much greater the star would expand. Therefore the correct answer is C: The inward force of gravity is balanced by the outward pressure of the hot gas and radiation.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igphy_space_s3_008', 'topic_igcse_physics_space', 'subj_igcse_physics', 'igcse', NULL, NULL, 'Light from the Sun takes about 500 s to reach the Earth. Taking the speed of light as 3.0 × 10⁸ m/s, calculate the distance from the Sun to the Earth.', 'multiple_choice', NULL, '["A. 1.5 × 10⁹ m","B. 6.0 × 10⁵ m","C. 1.5 × 10¹³ m","D. 1.5 × 10¹¹ m"]', 'D', 'Distance = speed × time = 3.0 × 10⁸ × 500 = 1.5 × 10¹¹ m (about 150 million kilometres). (1.5 × 10⁹ m misreads the 500 s as 5 s; 6.0 × 10⁵ m divides the speed by the time; 1.5 × 10¹³ m is a power-of-ten slip.) Therefore the correct answer is D: 1.5 × 10¹¹ m.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_cambridge');
INSERT INTO _migration_615_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_615_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_615_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'igcse-physics-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Physics (0625) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-physics-0625/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_615_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'igcse-physics-sprint3-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Physics (0625) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-physics-0625/', 0, 1 FROM _migration_615_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_615_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_615_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 8 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_615_expected e ON e.id = r.question_id WHERE r.batch_id IS 'igcse-physics-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Physics (0625) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-physics-0625/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 8 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_615_expected e ON e.id = q.id) = 8 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_615_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 0 THEN 1 ELSE 0 END;
